import React,{useEffect,useMemo,useRef,useState}from'react';
import{createRoot}from'react-dom/client';
import{Activity,AlertTriangle,ArrowRight,Award,BadgeCheck,BookMarked,BookOpen,Bookmark,BookmarkCheck,Building2,Check,CheckCircle2,ChevronLeft,ChevronRight,Circle,CircleHelp,ClipboardCheck,Clock,Compass,Database,Download,ExternalLink,Eye,FileCheck,FileCheck2,FileText,Files,Filter,FlaskConical,GitBranch,GraduationCap,Home,Image as ImageIcon,Inbox,Info,Layers3,Library,Lightbulb,Lock,Map as MapIcon,Maximize2,Menu,MessageSquareText,Milestone,PanelLeftClose,PanelLeftOpen,Pause,Play,RefreshCw,RotateCcw,Route,Scale,Search,ShieldCheck,Sparkles,StickyNote,Table2,Target,Trees,Trophy,X,ZoomIn,ZoomOut}from'lucide-react';
import popDataUrl from'./data/pop-content.json?url';
import flowDataUrl from'./data/flowcharts-content.json?url';
import{featuredMedia,flowSpecs,questionBank,scenarios,trackGroups,tracks}from'./courseData';
import{loadProfile,saveProfile,hasAccount,registerCertificate,certificateSvg,downloadSvg}from'./profile';
import'./styles.css';

const[popData,flowData]=await Promise.all([
 fetch(popDataUrl).then(r=>r.json()),
 fetch(flowDataUrl).then(r=>r.json()),
]);

// Sob deploy em subcaminho (GitHub Pages), os caminhos absolutos dos dados precisam do prefixo da base
const BASE=(import.meta.env.BASE_URL||'/').replace(/\/$/,'');
const wb=p=>typeof p==='string'&&p.startsWith('/')?BASE+p:p;
if(BASE){const PATH_KEYS=new Set(['publicPath','src','poster','captions']);const walk=o=>{if(Array.isArray(o))o.forEach(walk);else if(o&&typeof o==='object'){for(const k of Object.keys(o)){if(PATH_KEYS.has(k)&&typeof o[k]==='string'&&o[k].startsWith('/'))o[k]=BASE+o[k];else walk(o[k])}}};walk(popData);walk(flowData);walk(featuredMedia);}

const TRACK_ICONS={Compass,Scale,Inbox,GitBranch,FileCheck,Milestone,RefreshCw,ShieldCheck,Files,Map:MapIcon,Trees,Building2,ClipboardCheck,BadgeCheck,Library};

const STORAGE_KEY='academia-iat-progress-v2';
const NAV=[['dashboard','Visão geral',Home],['formacao','Formação',BookOpen],['fluxos','Fluxogramas',GitBranch],['laboratorio','Laboratório',FlaskConical],['avaliacoes','Avaliações',ClipboardCheck],['biblioteca','Biblioteca',Library],['perfil','Meu perfil',BadgeCheck]];
const blockMap=new Map(popData.blocks.map(b=>[b.id,b]));
const tableMap=new Map(popData.tables.map(t=>[t.id,t]));
const figureByBlock=new Map(popData.figures.map(f=>[f.blockId,f]));
const sectionMap=new Map(popData.sections.map(s=>[s.id,s]));

function useStoredState(){
 const initial={completed:[],bookmarks:[],notes:{},quizScores:{},labs:{},lastLesson:null,videoSeen:[],streak:1};
 const[state,setState]=useState(()=>{try{return{...initial,...JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}')}}catch{return initial}});
 useEffect(()=>{localStorage.setItem(STORAGE_KEY,JSON.stringify(state))},[state]);
 return[state,setState];
}
function norm(v=''){return v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function assignedTrack(section){
 const n=section.number||'';
 if(/^18\.(10|11|12|13)/.test(n))return'm09';
 if(/^(Anexo|Referências)/.test(n))return'm14';
 const root=n.includes('.')?n.split('.')[0]:n;
 for(const t of tracks){if(t.id==='m09'||t.id==='m14')continue;if(t.sections.includes(root)||(!n&&t.id==='m00'))return t.id}
 return'm14';
}
const lessons=popData.sections.filter(s=>s.title&&!/sumário navegável|índice de fluxogramas|índice navegável/i.test(s.title)).map((s,i)=>({...s,trackId:assignedTrack(s),order:i,minutes:Math.max(4,Math.min(28,Math.round((s.blockIds?.length||1)*1.8)+4))}));
const lessonMap=new Map(lessons.map(l=>[l.id,l]));
const trackLessons=new Map(tracks.map(t=>[t.id,lessons.filter(l=>l.trackId===t.id)]));
function trackProgress(id,state){const ls=trackLessons.get(id)||[];return ls.length?Math.round(ls.filter(l=>state.completed.includes(l.id)).length/ls.length*100):0}
function sectionText(section){return(section.blockIds||[]).map(id=>{const b=blockMap.get(id);return b?.paragraph?.text||b?.caption||''}).filter(Boolean).join(' ')}
function firstLesson(trackId){return(trackLessons.get(trackId)||[])[0]}

const VIEW_IDS=['dashboard','formacao','fluxos','laboratorio','avaliacoes','biblioteca','perfil'];
function parseHash(){const h=((typeof location!=='undefined'&&location.hash)||'').replace(/^#\/?/,'');if(!h)return{view:'dashboard',lesson:null};const i=h.indexOf('/');const seg=i<0?h:h.slice(0,i);const rest=i<0?'':h.slice(i+1);if(seg==='aula'&&rest)return{view:'lesson',lesson:decodeURIComponent(rest)};if(VIEW_IDS.includes(seg))return{view:seg,lesson:null};return{view:'dashboard',lesson:null};}
function pushHash(t){if(typeof location==='undefined')return;if(location.hash===t)return;try{history.pushState(null,'',t)}catch{location.hash=t}}
function App(){
 const [profile,setProfileRaw]=useState(()=>loadProfile());
 const setProfile=(p)=>{const v=typeof p==='function'?p(profile):p;setProfileRaw(v);saveProfile(v);};
 const[state,setState]=useStoredState();
 const _init=parseHash();
 const[view,setView]=useState(_init.view);
 const[selectedLesson,setSelectedLesson]=useState(()=>_init.lesson&&lessonMap.has(_init.lesson)?_init.lesson:(lessonMap.has(state.lastLesson)?state.lastLesson:firstLesson('m00')?.id));
 const[menuOpen,setMenuOpen]=useState(false),[searchOpen,setSearchOpen]=useState(false),[toast,setToast]=useState('');
 const progress=Math.round(state.completed.length/lessons.length*100);
 useEffect(()=>{const fn=e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setSearchOpen(true)}if(e.key==='Escape')setSearchOpen(false)};window.addEventListener('keydown',fn);return()=>window.removeEventListener('keydown',fn)},[]);
 useEffect(()=>{if(toast){const id=setTimeout(()=>setToast(''),2600);return()=>clearTimeout(id)}},[toast]);
 useEffect(()=>{const onNav=()=>{const p=parseHash();if(p.view==='lesson'){if(p.lesson&&lessonMap.has(p.lesson)){setSelectedLesson(p.lesson);setState(s=>s.lastLesson===p.lesson?s:{...s,lastLesson:p.lesson})}setView('lesson')}else setView(p.view);setMenuOpen(false);setSearchOpen(false)};window.addEventListener('popstate',onNav);window.addEventListener('hashchange',onNav);return()=>{window.removeEventListener('popstate',onNav);window.removeEventListener('hashchange',onNav)}},[]);
 function go(next){setView(next);setMenuOpen(false);pushHash(next==='dashboard'?'#/':'#/'+next);scrollTo({top:0,behavior:'smooth'})}
 function openLesson(id){if(!id)return;setSelectedLesson(id);setState(s=>({...s,lastLesson:id}));setView('lesson');setSearchOpen(false);setMenuOpen(false);pushHash('#/aula/'+encodeURIComponent(id));scrollTo({top:0,behavior:'smooth'})}
 function complete(id){setState(s=>({...s,completed:s.completed.includes(id)?s.completed.filter(x=>x!==id):[...s.completed,id]}));setToast(state.completed.includes(id)?'Aula marcada como não concluída':'Aula concluída e progresso salvo')}
 function bookmark(id){setState(s=>({...s,bookmarks:s.bookmarks.includes(id)?s.bookmarks.filter(x=>x!==id):[...s.bookmarks,id]}));setToast(state.bookmarks.includes(id)?'Favorito removido':'Aula salva nos favoritos')}
 let content={dashboard:<Dashboard state={state} progress={progress} go={go} openLesson={openLesson}/>,formacao:<Formation state={state} openLesson={openLesson}/>,fluxos:<Flowcharts state={state} setState={setState}/>,laboratorio:<Laboratory state={state} setState={setState}/>,avaliacoes:<Assessments state={state} setState={setState}/>,biblioteca:<KnowledgeLibrary state={state} openLesson={openLesson}/>,perfil:<Profile state={state} progress={progress} profile={profile} setProfile={setProfile} go={go} openLesson={openLesson}/>,lesson:<Lesson lesson={lessonMap.get(selectedLesson)||lessons[0]} state={state} setState={setState} openLesson={openLesson} complete={complete} bookmark={bookmark} go={go}/>}[view];
 return <div className="app-shell">
  <Topbar onMenu={()=>setMenuOpen(v=>!v)} onSearch={()=>setSearchOpen(true)} progress={progress} profile={profile} onProfile={()=>go('perfil')}/>
  <Sidebar view={view} go={go} open={menuOpen}/>
  {menuOpen&&<button className="nav-scrim" aria-label="Fechar menu" onClick={()=>setMenuOpen(false)}/>} 
  <main className={'main '+(view==='lesson'?'lesson-main':'')}>{content}</main>
  {searchOpen&&<GlobalSearch close={()=>setSearchOpen(false)} openLesson={openLesson}/>} 
  {toast&&<div className="toast"><CheckCircle2/>{toast}</div>}
 </div>
}

function Profile({state,progress,profile,setProfile,go,openLesson}){
 const conta=hasAccount(profile);
 const [editando,setEditando]=useState(!conta);
 const [form,setForm]=useState({name:profile.name||'',role:profile.role||'',unit:profile.unit||''});
 const salvar=(e)=>{e&&e.preventDefault&&e.preventDefault();const nome=(form.name||'').trim();if(!nome)return;setProfile(pr=>({...pr,name:nome,role:(form.role||'').trim(),unit:(form.unit||'').trim(),createdAt:pr.createdAt||new Date().toISOString()}));setEditando(false);};
 const mods=tracks.map(t=>({t,p:trackProgress(t.id,state)}));
 const concluidos=mods.filter(m=>m.p===100).length;
 const hoje=()=>new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'});
 const build=(typeof document!=='undefined'&&document.querySelector('meta[name=build]')?.content)||'local';
 const baixarCert=(label,percent)=>{const nowIso=new Date().toISOString();setProfile(pr=>registerCertificate(pr,label,percent,nowIso));const svg=certificateSvg({name:profile.name,label,dateLabel:'Emitido em '+hoje(),percent,buildId:build});downloadSvg('certificado-'+label.toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,40)+'.svg',svg);};
 if(!conta||editando){
  return <div className="page profile-page"><PageHeader icon={BadgeCheck} kicker="Meu perfil" title={conta?'Editar meu perfil':'Criar meu perfil'} subtitle="Seu progresso e seus certificados ficam vinculados a este perfil."/>
   <form className="profile-form" onSubmit={salvar}><label>Nome<input value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder="Como você quer ser identificado" autoFocus/></label>
   <label>Cargo ou função<input value={form.role} onChange={e=>setForm(f=>({...f,role:e.target.value}))} placeholder="Opcional"/></label>
   <label>Órgão ou setor<input value={form.unit} onChange={e=>setForm(f=>({...f,unit:e.target.value}))} placeholder="Opcional"/></label>
   <div className="profile-actions"><button type="submit" className="primary">{conta?'Salvar':'Criar perfil'} <Check/></button>{conta&&<button type="button" className="text-action" onClick={()=>setEditando(false)}>Cancelar</button>}</div>
   <p className="profile-note">Registro pessoal de estudo, guardado apenas neste navegador. Não é login seguro nem credencial institucional do IAT.</p></form></div>;
 }
 return <div className="page profile-page"><PageHeader icon={BadgeCheck} kicker="Meu perfil" title={profile.name} subtitle={[profile.role,profile.unit].filter(Boolean).join(' · ')||'Registro pessoal de estudo'}/>
  <section className="profile-grid">
   <article className="profile-card profile-progress"><h3>Progresso do curso</h3><div className="pring" style={{'--v':progress}}><strong>{progress}%</strong></div><small>{state.completed.length} de {lessons.length} tópicos concluídos</small><small>{concluidos} de {tracks.length} módulos completos</small></article>
   <article className="profile-card profile-personal"><h3>Meus dados</h3><dl><dt>Nome</dt><dd>{profile.name}</dd><dt>Cargo</dt><dd>{profile.role||'—'}</dd><dt>Órgão</dt><dd>{profile.unit||'—'}</dd><dt>Desde</dt><dd>{profile.createdAt?new Date(profile.createdAt).toLocaleDateString('pt-BR'):'—'}</dd></dl><button className="text-action" onClick={()=>{setForm({name:profile.name,role:profile.role,unit:profile.unit});setEditando(true);}}>Editar dados</button></article>
   <article className="profile-card profile-activity"><h3>Atividade</h3><ul className="profile-activity-list"><li><Bookmark size={15}/> {state.bookmarks.length} favoritos</li><li><StickyNote size={15}/> {Object.keys(state.notes||{}).length} anotações</li><li><CheckCircle2 size={15}/> {state.completed.length} tópicos feitos</li></ul>{state.lastLesson&&<button className="text-action" onClick={()=>openLesson(state.lastLesson)}>Continuar de onde parou <ArrowRight size={15}/></button>}</article>
  </section>
  <section className="profile-cert-block"><div className="section-title"><div><h2>Certificados</h2><p>Marcos de conclusão que você pode baixar. Cada um é um registro pessoal de estudo.</p></div><Award/></div>
   <div className="cert-course">{progress===100?<button className="primary" onClick={()=>baixarCert('Curso completo do POP',100)}><Download size={16}/> Baixar certificado do curso</button>:<p className="cert-locked">Conclua os {lessons.length} tópicos para liberar o certificado do curso completo. Faltam {lessons.length-state.completed.length}.</p>}</div>
   <h4>Por módulo</h4><ul className="cert-modules">{mods.map(({t,p})=><li key={t.id}><span className="cert-mod-code">{t.code}</span><span className="cert-mod-title">{t.title}</span><span className="cert-mod-bar"><i style={{width:p+'%'}}/></span><span className="cert-mod-pct">{p}%</span>{p===100?<button className="cert-mod-dl" onClick={()=>baixarCert('Módulo '+t.code+' — '+t.title,100)}><Download size={14}/></button>:<span className="cert-mod-pending">em curso</span>}</li>)}</ul></section>
  <p className="profile-note">Os certificados desta plataforma são registros pessoais de autoestudo. Não são documentos oficiais do Instituto Água e Terra.</p></div>;
}
function Topbar({onMenu,onSearch,progress,profile,onProfile}){const _n=((profile&&profile.name)||'').trim();const _acc=hasAccount(profile);const _ini=_acc?(_n.split(/\s+/).filter(Boolean).map(w=>w[0]).slice(0,2).join('').toUpperCase()||'IAT'):'+';return <header className="topbar"><button className="mobile-menu" onClick={onMenu} aria-label="Abrir menu"><Menu/></button><div className="compact-brand"><span className="brand-wave">IAT</span><div><strong>Academia de Licenciamento</strong><small>Hidrelétrico</small></div></div><button className="global-search" onClick={onSearch}><Search/><span>Buscar no POP, aulas e checklists</span><kbd>Ctrl K</kbd></button><div className="top-progress" title={`${progress}% concluído`}><span>{progress}%</span><i><em style={{width:`${progress}%`}}/></i></div><button className="profile" onClick={onProfile} title={_acc?'Ver meu perfil':'Criar meu perfil'}><span>{_ini}</span><div><strong>{_acc?_n.split(/\s+/)[0]:'Meu perfil'}</strong><small>{_acc?(profile.role||'Registro pessoal'):'Criar sua conta'}</small></div></button></header>}
function Sidebar({view,go,open}){return <aside className={'sidebar-v2 '+(open?'open':'')}><div className="brand-panel"><strong>Academia IAT</strong><span>Licenciamento<br/>Hidrelétrico</span><svg viewBox="0 0 150 38" aria-hidden="true"><path d="M3 25 C28 2 40 35 63 15 S102 30 147 8"/><path d="M3 31 C32 15 58 37 85 25 S120 22 147 18"/></svg></div><nav>{NAV.map(([id,label,Icon])=><button key={id} className={view===id||(view==='lesson'&&id==='formacao')?'active':''} onClick={()=>go(id)}><Icon/>{label}</button>)}</nav><div className="sidebar-help"><CircleHelp/><div><strong>Precisa de ajuda?</strong><small>Acesse o guia da plataforma</small></div><ChevronRight/></div><div className="source-lock"><ShieldCheck/><span>Conteúdo integral<br/><b>POP v1.2 · julho de 2026</b></span></div></aside>}

function Dashboard({state,progress,go,openLesson}){
 const continueLesson=lessonMap.get(state.lastLesson)||firstLesson('m02');
 const continueTrack=tracks.find(t=>t.id===continueLesson.trackId);
 const feat=featuredMedia[continueTrack.id];
 return <div className="page dashboard-page"><section className="dashboard-intro"><div><h1>Aprenda o procedimento.<br/>Pratique a decisão.</h1><p>Percorra o POP completo e desenvolva segurança para decidir com qualidade em cada etapa do licenciamento hidrelétrico.</p></div><div className="intro-stat"><span>Seu progresso</span><strong>{progress}%</strong><i><em style={{width:`${progress}%`}}/></i><small>{state.completed.length} de {lessons.length} tópicos concluídos</small></div></section>
 <section className="river-journey" aria-label="Percurso de aprendizagem"><div className="journey-head"><h2>Seu percurso pelo POP</h2><button onClick={()=>go('formacao')}>Ver formação completa <ArrowRight/></button></div><div className="river-line"><svg viewBox="0 0 1600 140" preserveAspectRatio="none" aria-hidden="true"><path className="river-shadow" d="M0 75 C120 10 230 125 350 62 S590 110 720 55 S950 110 1080 50 S1320 115 1600 52"/><path className="river-water" d="M0 75 C120 10 230 125 350 62 S590 110 720 55 S950 110 1080 50 S1320 115 1600 52"/></svg><div className="journey-track">{tracks.map((t,i)=>{let p=trackProgress(t.id,state);return <button key={t.id} className={p===100?'done':p>0?'current':''} onClick={()=>openLesson(firstLesson(t.id)?.id)}><span>{p===100?<Check/>:i+1}</span><strong>{t.code}</strong><small>{t.title}</small></button>})}</div></div><div className="journey-legend"><span><i className="dot done"/>Concluído</span><span><i className="dot current"/>Em andamento</span><span><i className="dot"/>Não iniciado</span></div></section>
 <section className="dashboard-feature"><div className="feature-media"><video key={feat?.src} poster={feat?.poster||wb("/media/analista-licenciamento.png")} controls preload="metadata" playsInline>{feat?.src&&<source src={feat.src} type="video/mp4"/>}{feat?.captions&&<track kind="captions" srcLang="pt" src={feat.captions} label="Português" default/>}</video><span>Vídeo em destaque{feat?.title?`: ${feat.title}`:""}</span></div><div className="feature-copy"><small>{continueTrack.code} · CONTINUE DE ONDE PAROU</small><h2>{continueLesson.fullTitle||continueLesson.title}</h2><p>{continueTrack.summary}</p><div className="feature-meta"><span><Clock/> {continueLesson.minutes} min</span><span><Layers3/> {trackLessons.get(continueTrack.id).length} tópicos</span></div><button className="primary" onClick={()=>openLesson(continueLesson.id)}>Continuar aula <Play/></button><button className="text-action" onClick={()=>go('formacao')}>Ver todas as aulas <ArrowRight/></button></div><TodayPlan go={go}/></section>
 <section className="dashboard-bottom"><article className="flow-preview"><div className="section-title"><div><h2>Prévia do fluxo geral</h2><p>Veja a análise ganhar forma, etapa por etapa.</p></div><button onClick={()=>go('fluxos')}>Explorar <ExternalLink/></button></div><MiniFlow/></article><article className="coverage-card"><div className="section-title"><div><h2>Todo o POP, em um só lugar</h2><p>Extração auditada e vinculada às aulas.</p></div><Database/></div><div className="coverage-stats"><span><strong>{lessons.length}</strong>seções e tópicos</span><span><strong>61</strong>quadros e tabelas</span><span><strong>33</strong>figuras e fluxos</span><span><strong>2.690</strong>parágrafos</span></div><button onClick={()=>go('biblioteca')}>Abrir biblioteca integral <ArrowRight/></button></article></section></div>
}
function TodayPlan({go}){return <aside className="today-plan"><div><h2>Seu plano de hoje</h2><span>≈ 45 min</span></div>{[[BookOpen,'Continuar aula','Triagem e leitura do processo','formacao'],[FileCheck2,'Checklist','Conferência documental','biblioteca'],[FlaskConical,'Laboratório','Simule uma análise','laboratorio'],[ClipboardCheck,'Avaliação rápida','Teste seus conhecimentos','avaliacoes']].map(([Icon,a,b,v],i)=><button key={a} onClick={()=>go(v)}><span className={`plan-icon c${i}`}><Icon/></span><span><strong>{a}</strong><small>{b}</small></span><ChevronRight/></button>)}</aside>}
function MiniFlow(){return <div className="mini-flow">{['Receber','Conferir','Enquadrar','Analisar','Registrar'].map((x,i)=><React.Fragment key={x}><div style={{'--delay':`${i*.35}s`}}><span>{i+1}</span><strong>{x}</strong></div>{i<4&&<i><ArrowRight/></i>}</React.Fragment>)}</div>}

function Formation({state,openLesson}){
 const[openTrack,setOpenTrack]=useState('m02'),[filter,setFilter]=useState('');
 return <div className="page"><PageHeader title="Formação completa" subtitle="15 módulos conectam cada seção do POP a objetivos, conteúdo-fonte, prática e avaliação." icon={GraduationCap}/><div className="formation-toolbar"><div><Search/><input value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Filtrar módulos ou aulas"/></div><span>{lessons.length} tópicos · {tracks.reduce((a,t)=>a+(trackLessons.get(t.id)?.reduce((x,l)=>x+l.minutes,0)||0),0)} min</span></div><div className="curriculum">{trackGroups.map(group=><section key={group.title}><div className="group-title"><span>{group.title}</span><i/></div>{group.ids.map(id=>{const t=tracks.find(x=>x.id===id),ls=(trackLessons.get(id)||[]).filter(l=>norm(l.title+' '+l.number).includes(norm(filter))),p=trackProgress(id,state),Icon=TRACK_ICONS[t.icon]||BookOpen;if(filter&&!norm(t.title).includes(norm(filter))&&!ls.length)return null;return <article className={'track-row '+(openTrack===id?'expanded':'')} key={id}><button className="track-summary" onClick={()=>setOpenTrack(openTrack===id?'':id)}><span className="track-icon" style={{'--track':t.color}}><Icon/></span><span className="track-copy"><small>{t.code}</small><strong>{t.title}</strong><em>{t.summary}</em></span><span className="track-metrics"><b>{p}%</b><i><em style={{width:`${p}%`}}/></i><small>{state.completed.filter(x=>ls.some(l=>l.id===x)).length}/{ls.length} tópicos</small></span><ChevronRight/></button>{openTrack===id&&<div className="lesson-list">{ls.map((l,i)=><button key={l.id} onClick={()=>openLesson(l.id)}><span className={state.completed.includes(l.id)?'complete':''}>{state.completed.includes(l.id)?<Check/>:i+1}</span><span><strong>{l.number?`${l.number} `:''}{l.title}</strong><small>{l.minutes} min · Conteúdo integral do POP</small></span>{state.bookmarks.includes(l.id)&&<BookmarkCheck className="saved"/>}<ChevronRight/></button>)}</div>}</article>})}</section>)}</div></div>
}

function Lesson({lesson,state,setState,openLesson,complete,bookmark,go}){
 const[tab,setTab]=useState('aula'),[outlineOpen,setOutlineOpen]=useState(true);const track=tracks.find(t=>t.id===lesson.trackId)||tracks[0];const media=featuredMedia[track.id];const ls=trackLessons.get(track.id)||[];const index=ls.findIndex(l=>l.id===lesson.id);const next=ls[index+1]||lessons[lesson.order+1];const blocks=(lesson.blockIds||[]).map(id=>blockMap.get(id)).filter(b=>b&&!b.navigationOnly);const tables=blocks.filter(b=>b.type==='table').map(b=>tableMap.get(b.tableId)).filter(Boolean);const figures=popData.figures.filter(f=>f.blockId&&lesson.blockIds?.includes(f.blockId));const note=state.notes[lesson.id]||'';
 useEffect(()=>{scrollTo({top:0})},[lesson.id]);
 function setNote(v){setState(s=>({...s,notes:{...s.notes,[lesson.id]:v}}))}
 return <div className={'lesson-layout '+(!outlineOpen?'outline-collapsed':'')}><aside className="lesson-outline"><button className="outline-toggle" onClick={()=>setOutlineOpen(v=>!v)}>{outlineOpen?<PanelLeftClose/>:<PanelLeftOpen/>}</button>{outlineOpen&&<><button className="back-course" onClick={()=>go('formacao')}><ChevronLeft/> Voltar à formação</button><div className="outline-track"><span style={{background:track.color}}>{track.code}</span><div><strong>{track.title}</strong><small>{trackProgress(track.id,state)}% concluído</small></div></div><div className="outline-lessons">{ls.map((l,i)=><button className={l.id===lesson.id?'active':''} key={l.id} onClick={()=>openLesson(l.id)}><span className={state.completed.includes(l.id)?'done':''}>{state.completed.includes(l.id)?<Check/>:i+1}</span><span>{l.number&&<small>{l.number}</small>}<strong>{l.title}</strong></span></button>)}</div></>}</aside><div className="lesson-content"><div className="breadcrumbs"><button onClick={()=>go('formacao')}>Formação</button><ChevronRight/><span>{track.code}</span><ChevronRight/><span>{lesson.number||'Introdução'}</span></div><header className="lesson-header"><div><h1>{lesson.number&&<span>{lesson.number}</span>} {lesson.title}</h1><p><Target/> Objetivo: compreender os critérios desta seção, aplicar o método ao caso concreto e registrar uma decisão rastreável.</p></div><button className="bookmark-btn" onClick={()=>bookmark(lesson.id)}>{state.bookmarks.includes(lesson.id)?<BookmarkCheck/>:<Bookmark/>}</button></header><VideoLesson media={media} track={track}/><div className="lesson-tabs" role="tablist">{[['aula','Aula',BookOpen],['fonte','Conteúdo integral',FileText],['materiais','Quadros e figuras',Layers3],['notas','Anotações',StickyNote]].map(([id,label,Icon])=><button role="tab" aria-selected={tab===id} className={tab===id?'active':''} onClick={()=>setTab(id)} key={id}><Icon/>{label}{id==='materiais'&&<span>{tables.length+figures.length}</span>}</button>)}</div>{tab==='aula'&&<LessonOverview lesson={lesson} blocks={blocks} checked={state.checks?.[lesson.id]||[]} toggleCheck={i=>setState(s=>{const cur=s.checks?.[lesson.id]||[];const nx=cur.includes(i)?cur.filter(x=>x!==i):[...cur,i];return{...s,checks:{...(s.checks||{}),[lesson.id]:nx}}})}/>} {tab==='fonte'&&<SourceContent blocks={blocks}/>} {tab==='materiais'&&<LessonMaterials tables={tables} figures={figures}/>} {tab==='notas'&&<Notes value={note} setValue={setNote}/>}<footer className="lesson-footer"><button className={state.completed.includes(lesson.id)?'completed':''} onClick={()=>complete(lesson.id)}>{state.completed.includes(lesson.id)?<CheckCircle2/>:<Circle/>}{state.completed.includes(lesson.id)?'Aula concluída':'Marcar como concluída'}</button>{next&&<button className="next-lesson" onClick={()=>openLesson(next.id)}><span><small>PRÓXIMO TÓPICO</small><strong>{next.number?`${next.number} `:''}{next.title}</strong></span><ArrowRight/></button>}</footer></div><aside className="lesson-context"><div className="context-sticky"><h3>Nesta aula</h3><div className="context-progress"><span>Progresso do módulo</span><b>{trackProgress(track.id,state)}%</b><i><em style={{width:`${trackProgress(track.id,state)}%`}}/></i></div><nav><button onClick={()=>setTab('aula')}><Target/>Resumo guiado<CheckCircle2/></button><button onClick={()=>setTab('fonte')}><FileText/>Texto integral<Circle/></button><button onClick={()=>setTab('materiais')}><Layers3/>{tables.length} tabelas · {figures.length} figuras<Circle/></button><button onClick={()=>setTab('notas')}><StickyNote/>Caderno pessoal<Circle/></button></nav><div className="quick-tip"><Lightbulb/><div><strong>Regra de ouro</strong><p>Identifique documento, fundamento, suficiência, consequência e encaminhamento. Não comece pela conclusão.</p></div></div></div></aside></div>
}
function VideoLesson({media,track}){return <figure className="video-lesson"><video controls preload="metadata" poster={media.poster}><source src={media.src} type="video/mp4"/><track default kind="captions" src={media.captions} srcLang="pt-BR" label="Português"/>Seu navegador não suporta vídeo HTML5.</video><figcaption><span><Play/>{media.title}</span><small>Microaula animada · 20 s · {track.code}</small></figcaption></figure>}
function LessonOverview({lesson,blocks,checked=[],toggleCheck}){const paragraphs=blocks.filter(b=>b.type==='paragraph'&&b.paragraph?.text).slice(0,8);const steps=paragraphs.filter(b=>/^\d+\./.test(b.paragraph.text));const shown=steps.slice(0,8);const doneN=shown.filter((_,i)=>checked.includes(i)).length;return <article className="lesson-article"><h2>A sequência que sustenta uma decisão segura</h2><p className="lead">Leia o conteúdo-fonte com uma pergunta em mente: qual evidência permite avançar, qual lacuna impede uma conclusão segura e qual providência é proporcional?</p>{steps.length>=3?<div className="lesson-checklist"><div className="lc-head"><strong><ClipboardCheck size={16}/> Checklist da aula</strong><span>{doneN}/{shown.length} verificados</span><i><em style={{width:`${shown.length?doneN/shown.length*100:0}%`}}/></i></div>{shown.map((b,i)=>{const on=checked.includes(i);return <button type="button" key={b.id} className={on?'lc-item done':'lc-item'} aria-pressed={on} onClick={()=>toggleCheck&&toggleCheck(i)}>{on?<CheckCircle2/>:<Circle/>}<span>{b.paragraph.text.replace(/^\d+\.\s*/,'')}</span></button>})}{doneN===shown.length&&<div className="lc-complete"><Check/> Checklist concluído — você percorreu todos os pontos desta aula.</div>}</div>:<div className="concept-strip">{paragraphs.slice(0,4).map((b,i)=><div key={b.id}><span>{i+1}</span><p>{b.paragraph.text}</p></div>)}</div>}<div className="analysis-alert"><AlertTriangle/><div><strong>Alerta de análise</strong><p>O conteúdo desta aula apoia a aplicação do POP. Confirme a norma vigente, as regras de transição e as orientações jurídica e institucional aplicáveis ao processo concreto.</p></div></div><div className="example-compare"><div className="bad"><X/><div><strong>Atalho arriscado</strong><p>Assumir a conclusão e procurar documentos apenas para confirmá-la.</p></div></div><div className="good"><Check/><div><strong>Análise rastreável</strong><p>Confrontar evidências, registrar limitações e deixar a conclusão resultar do percurso.</p></div></div></div><button className="source-jump" onClick={()=>document.querySelector('[role=tab][aria-selected=false]')?.focus()}><BookMarked/> Consulte o texto integral na aba ao lado</button></article>}
function SourceContent({blocks}){if(!blocks.length)return <Empty text="Esta seção funciona como elemento de organização do documento."/>;return <article className="source-content"><div className="source-notice"><ShieldCheck/><p><strong>Conteúdo integral extraído do documento.</strong> A ordem, os textos e as tabelas foram preservados; blocos de sumário redundantes não entram na experiência didática.</p></div>{blocks.map(b=><BlockRenderer block={b} key={b.id}/>)}</article>}
function BlockRenderer({block}){if(block.type==='table'){const table=tableMap.get(block.tableId);return table?<TableRenderer table={table}/>:null}const p=block.paragraph;if(!p?.text)return null;const figure=figureByBlock.get(block.id);let text=p.text;let cls=p.semanticType==='list-item'||p.list?'source-list':'';return <React.Fragment>{p.headingLevel?<h3>{text}</h3>:<p className={cls}>{text}</p>}{figure&&<figure className="source-figure"><img src={figure.publicPath} alt={figure.altText||figure.title}/><figcaption>{figure.caption}</figcaption></figure>}</React.Fragment>}
function TableRenderer({table,compact=false}){const[all,setAll]=useState(false);const rows=compact||all?table.rows:table.rows.slice(0,12);return <figure className="data-table"><figcaption><span>{table.labelType} {table.labelNumber}</span><strong>{table.title}</strong><small>{table.rowCount} linhas × {table.columnCount} colunas</small></figcaption><div className="table-scroll"><table><tbody>{rows.map((r,ri)=><tr key={ri} className={r.isHeader?'header-row':''}>{r.cells.map((c,ci)=>{const Tag=r.isHeader?'th':'td';return <Tag key={ci}>{c.text}</Tag>})}</tr>)}</tbody></table></div>{!compact&&table.rows.length>12&&<button onClick={()=>setAll(v=>!v)}>{all?'Mostrar menos':`Mostrar todas as ${table.rows.length} linhas`}<ChevronRight/></button>}</figure>}
function LessonMaterials({tables,figures}){if(!tables.length&&!figures.length)return <Empty text="Este tópico não possui quadro ou figura próprio. Consulte o conteúdo integral para o texto-fonte."/>;return <div className="materials-view">{figures.map(f=><figure className="material-figure" key={f.id}><img src={f.publicPath} alt={f.altText||f.title}/><figcaption>{f.caption}</figcaption><a href={f.publicPath} download><Download/> Baixar imagem</a></figure>)}{tables.map(t=><TableRenderer table={t} key={t.id}/>)}</div>}
function Notes({value,setValue}){return <section className="notes-panel"><div><StickyNote/><span><strong>Seu caderno</strong><small>Salvo automaticamente neste dispositivo</small></span></div><textarea value={value} onChange={e=>setValue(e.target.value)} placeholder="Registre dúvidas, exemplos do seu trabalho e pontos para revisar..."/><div className="note-prompts"><button onClick={()=>setValue(value+'\n• Evidência que preciso verificar: ')}>Evidência a verificar</button><button onClick={()=>setValue(value+'\n• Dúvida para validação: ')}>Dúvida para validação</button><button onClick={()=>setValue(value+'\n• Aplicação no meu processo: ')}>Aplicação prática</button></div></section>}

function shuffleIdx(n){const a=[...Array(n).keys()];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function FlowBuilder({flow,record}){const N=flow.nodes.length;const[pool,setPool]=useState(()=>shuffleIdx(N));const[built,setBuilt]=useState([]);useEffect(()=>{setPool(shuffleIdx(N));setBuilt([])},[flow.id]);const done=built.length===N;const score=built.filter((idx,k)=>idx===k).length;useEffect(()=>{if(done)record&&record(flow.id,score,N)},[done]);function place(idx){setBuilt(b=>[...b,idx]);setPool(p=>p.filter(x=>x!==idx))}function undo(){if(!built.length)return;const last=built[built.length-1];setBuilt(b=>b.slice(0,-1));setPool(p=>[...p,last])}function reset(){setPool(shuffleIdx(N));setBuilt([])}return <div className="flow-builder"><div className="fb-head"><h3>Monte a sequência correta</h3><p>Clique nas etapas na ordem em que acontecem no fluxo. A conferência é imediata.</p></div><ol className="fb-slots">{Array.from({length:N}).map((_,k)=>{const idx=built[k];const filled=idx!==undefined;const ok=filled&&idx===k;return <li key={k} className={filled?(ok?'ok':'bad'):'open'}><span>{k+1}</span>{filled?<><strong>{flow.nodes[idx]}</strong>{ok?<Check/>:<X/>}</>:<em>Escolha a etapa {k+1}</em>}</li>})}</ol><div className="fb-pool">{pool.length?pool.map(idx=><button key={idx} onClick={()=>place(idx)}>{flow.nodes[idx]}</button>):<span className="fb-empty">Todas as etapas foram posicionadas.</span>}</div><div className="fb-actions"><button className="text-action" onClick={undo} disabled={!built.length}><RotateCcw size={15}/> Desfazer</button><button className="text-action" onClick={reset}><RefreshCw size={15}/> Recomeçar</button></div>{done&&<div className={'fb-result '+(score===N?'perfect':'')}>{score===N?<CheckCircle2/>:<AlertTriangle/>}<div><strong>{score} de {N} etapas na posição correta</strong><p>{score===N?'Sequência perfeita. Você domina a ordem deste fluxo.':'Revise as etapas em vermelho e recomece para fixar a ordem.'}</p></div></div>}</div>}
function Flowcharts({state,setState}){const[selected,setSelected]=useState(flowSpecs[0].id),[variant,setVariant]=useState('simplificado'),[active,setActive]=useState(0),[playing,setPlaying]=useState(true),[zoom,setZoom]=useState(1),[mode,setMode]=useState('explorar'),[fit,setFit]=useState(true);const flow=flowSpecs.find(f=>f.id===selected);useEffect(()=>{setActive(0);setZoom(1)},[selected]);useEffect(()=>{if(!playing||mode!=='explorar')return;const id=setInterval(()=>setActive(a=>(a+1)%flow.nodes.length),1600);return()=>clearInterval(id)},[playing,flow,mode]);const source=flowData.flowcharts.find(f=>f.number===flow.imageNumber&&f.variant===variant);const record=(id,score,total)=>setState&&setState(s=>({...s,flows:{...(s.flows||{}),[id]:{score,total,date:new Date().toISOString()}}}));const best=state&&state.flows&&state.flows[selected];return <div className="page"><PageHeader title="Fluxogramas interativos" subtitle="Explore os sete fluxos em versão original, simplificada e completa — e acompanhe o caminho ativo." icon={Route}/><div className="flow-workspace"><aside className="flow-menu">{flowSpecs.map((f,i)=><button className={selected===f.id?'active':''} key={f.id} onClick={()=>setSelected(f.id)}><span>{i+1}</span><div><strong>{f.title}</strong><small>{state&&state.flows&&state.flows[f.id]?`Montado ${state.flows[f.id].score}/${state.flows[f.id].total}`:'Explorar e montar'}</small></div><ChevronRight/></button>)}</aside><section className="flow-canvas"><div className="flow-mode-tabs"><button className={mode==='explorar'?'active':''} onClick={()=>setMode('explorar')}><Eye/> Explorar</button><button className={mode==='montar'?'active':''} onClick={()=>setMode('montar')}><GitBranch/> Montar o fluxo</button>{best&&<span className="fb-badge"><CheckCircle2/> {best.score}/{best.total}</span>}</div>{mode==='explorar'?<><div className="flow-toolbar"><span className="flow-toolbar-label">Percurso didático em {flow.nodes.length} etapas</span><div><button onClick={()=>setPlaying(v=>!v)}>{playing?<Pause/>:<Play/>}</button><button onClick={()=>setZoom(z=>Math.max(.7,z-.1))}><ZoomOut/></button><span>{Math.round(zoom*100)}%</span><button onClick={()=>setZoom(z=>Math.min(1.4,z+.1))}><ZoomIn/></button></div></div><div className="interactive-flow" style={{transform:`scale(${zoom})`}}>{flow.nodes.map((n,i)=><React.Fragment key={n}><button className={(i===active?'active ':'')+(i<active?'visited ':'')+(n.includes('?')?'decision':'')} onClick={()=>{setActive(i);setPlaying(false)}}><span>{i+1}</span><strong>{n}</strong><small>{i===active?'Etapa em foco':i<active?'Percorrida':'A seguir'}</small></button>{i<flow.nodes.length-1&&<div className={(i<active?'lit':'')}><ArrowRight/></div>}</React.Fragment>)}</div><div className="flow-insight"><Info/><div><small>ETAPA {active+1}</small><h3>{flow.nodes[active]}</h3><p>Abra o conteúdo do POP, confira as evidências e registre a motivação antes de avançar. Clique em qualquer nó para explorar.</p></div></div></>:<FlowBuilder flow={flow} record={record}/>}<section className="source-flow-panel"><div className="sfp-head"><span className="sfp-title"><Eye/> Fluxograma-fonte do POP</span><div className="variant-tabs">{[['original','Original'],['simplificado','Simplificado'],['completo','Completo']].map(([v,l])=><button className={variant===v?'active':''} onClick={()=>setVariant(v)} key={v}>{l}</button>)}</div><button className="sfp-fit" onClick={()=>setFit(f=>!f)}>{fit?'Ver em tamanho real':'Ajustar à largura'}</button>{source&&<a className="sfp-open" href={source.publicPath} target="_blank" rel="noreferrer"><Maximize2/> Nova aba</a>}</div>{source?<div className={'sfp-scroll '+(fit?'fit':'real')}><img key={source.publicPath} src={source.publicPath} alt={`${flow.title}, versão ${variant}`}/></div>:<p className="sfp-missing">Imagem não encontrada para esta versão.</p>}{source&&<small className="sfp-meta">Versão {variant} · {source.widthPx}×{source.heightPx}px · imagem integral do documento</small>}</section></section></div></div>}

function Laboratory({state,setState}){const[selected,setSelected]=useState(scenarios[2].id),[answers,setAnswers]=useState({}),[reason,setReason]=useState(''),[showResult,setShowResult]=useState(false);const s=scenarios.find(x=>x.id===selected);useEffect(()=>{setAnswers({});setReason('');setShowResult(false)},[selected]);const answered=Object.keys(answers).length;const score=s.questions.filter((q,i)=>answers[i]===q[1]).length;function finish(){setShowResult(true);setState(st=>({...st,labs:{...st.labs,[s.id]:{score,total:s.questions.length,date:new Date().toISOString()}}}))}return <div className="page lab-page"><PageHeader title="Pratique antes de assinar" subtitle="Laboratório didático: selecione evidências, tome decisões e compare sua fundamentação." icon={FlaskConical}/><div className="scenario-tabs">{scenarios.map(x=><button className={selected===x.id?'active':''} onClick={()=>setSelected(x.id)} key={x.id}>{x.label}{state.labs[x.id]&&<CheckCircle2/>}</button>)}</div><div className="lab-workspace"><section className="lab-canvas"><div className="case-header"><div><small>CENÁRIO · {s.type}</small><h2>{s.title}</h2></div><button><FileText/> Resumo do caso</button></div><div className="case-facts">{s.facts.map(f=><span key={f}><Activity/>{f}</span>)}</div><div className="decision-path"><div className="path-node complete"><span>1</span><strong>Triagem</strong><Check/></div>{s.questions.map((q,i)=><React.Fragment key={q[0]}><i className={answers[i]?'active':''}/><button className={'path-node '+(answers[i]?'complete ':'')+(i===answered?'current':'')} onClick={()=>{}}><span>{i+2}</span><strong>{['Documentação','Enquadramento','Análise técnica'][i]}</strong>{answers[i]?<Check/>:<Circle/>}</button></React.Fragment>)}<i className={answered===s.questions.length?'active':''}/><div className={'path-node '+(showResult?'complete':'')}><span>5</span><strong>Parecer</strong>{showResult?<Check/>:<Circle/>}</div></div><div className="lab-evidence"><div><h3>Evidências disponíveis</h3>{s.evidence.map(e=><button key={e}><FileText/><span>{e}<small>Documento do cenário</small></span><Eye/></button>)}</div><div className="question-stack"><h3>Decisões do percurso</h3>{s.questions.map((q,i)=><fieldset key={q[0]} className={i>answered?'locked':''}><legend>{i+1}. {q[0]}</legend>{i>answered?<span><Lock/> Responda à etapa anterior</span>:<div><button className={answers[i]==='sim'?'selected':''} onClick={()=>setAnswers(a=>({...a,[i]:'sim'}))}>Sim</button><button className={answers[i]==='nao'?'selected':''} onClick={()=>setAnswers(a=>({...a,[i]:'nao'}))}>Não</button></div>}</fieldset>)}</div></div></section><aside className="lab-inspector"><div><small>SEU PARECER DIDÁTICO</small><h2>Fundamente a decisão</h2><p>Relacione evidências, consequência técnica e encaminhamento.</p></div><textarea value={reason} onChange={e=>setReason(e.target.value)} placeholder="Escreva sua fundamentação..."/><div className="decision-readiness"><span>Decisões respondidas <b>{answered}/{s.questions.length}</b></span><i><em style={{width:`${answered/s.questions.length*100}%`}}/></i><span>Fundamentação <b>{reason.length}/120</b></span><i><em style={{width:`${Math.min(100,reason.length/120*100)}%`}}/></i></div><button className="primary" disabled={answered<s.questions.length||reason.length<30} onClick={finish}>Finalizar e ver debriefing <ArrowRight/></button><div className="lab-tip"><Lightbulb/><p><strong>Dica do laboratório</strong> Não procure apenas “sim” ou “não”: explicite por que a evidência é suficiente ou insuficiente.</p></div>{showResult&&<div className="debrief"><Trophy/><small>DEBRIEFING</small><h3>{score}/{s.questions.length} decisões alinhadas</h3><p>{s.outcome}</p><button onClick={()=>{setAnswers({});setReason('');setShowResult(false)}}><RotateCcw/> Tentar novamente</button></div>}</aside></div></div>}

function Assessments({state,setState}){const[track,setTrack]=useState('geral'),[started,setStarted]=useState(false),[index,setIndex]=useState(0),[answers,setAnswers]=useState({}),[revealed,setRevealed]=useState(false),[done,setDone]=useState(false);const questions=useMemo(()=>track==='geral'?questionBank.slice(0,12):questionBank.filter(q=>q.track===track),[track]);const q=questions[index];const score=questions.filter((x,i)=>answers[i]===x.answer).length;function reset(id=track){setTrack(id);setStarted(false);setIndex(0);setAnswers({});setRevealed(false);setDone(false)}function next(){if(index===questions.length-1){setDone(true);setState(s=>({...s,quizScores:{...s.quizScores,[track]:{score,total:questions.length,date:new Date().toISOString()}}}))}else{setIndex(i=>i+1);setRevealed(false)}}return <div className="page"><PageHeader title="Avaliações e domínio" subtitle="Questões comentadas transformam erro em revisão direcionada — sem esconder o fundamento." icon={ClipboardCheck}/>{!started?<div className="assessment-select"><section className="diagnostic"><div><Award/><span><small>AVALIAÇÃO INTEGRADORA</small><h2>Diagnóstico geral do POP</h2><p>12 questões selecionadas entre fundamentos, modalidades, estudos, PACUERA e conclusão técnica.</p></span></div><div className="assessment-meta"><span><Clock/> 15 min</span><span><MessageSquareText/> Feedback imediato</span><span><Trophy/> Registro de resultado</span></div><button onClick={()=>{reset('geral');setStarted(true)}}>Iniciar diagnóstico <ArrowRight/></button>{state.quizScores.geral&&<small>Último resultado: {state.quizScores.geral.score}/{state.quizScores.geral.total}</small>}</section><h2>Avaliações por módulo</h2><div className="module-tests">{tracks.filter(t=>questionBank.some(q=>q.track===t.id)).map(t=>{let qs=questionBank.filter(q=>q.track===t.id),last=state.quizScores[t.id];return <button key={t.id} onClick={()=>{reset(t.id);setStarted(true)}}><span style={{background:t.color}}>{t.code}</span><div><strong>{t.title}</strong><small>{qs.length} questões · feedback comentado</small></div>{last?<b>{last.score}/{last.total}</b>:<ChevronRight/>}</button>})}</div></div>:<section className="quiz-stage">{done?<div className="quiz-result"><div className="score-ring" style={{'--score':`${score/questions.length*100}%`}}><span><strong>{score}</strong>/{questions.length}</span></div><h2>{score/questions.length>=.8?'Domínio consistente':'Há pontos para revisar'}</h2><p>Você acertou {Math.round(score/questions.length*100)}%. Use o feedback abaixo para voltar às trilhas relacionadas.</p><div className="result-actions"><button onClick={()=>reset()}><RotateCcw/> Refazer</button><button className="primary" onClick={()=>setStarted(false)}>Escolher outra avaliação</button></div></div>:<><div className="quiz-top"><button onClick={()=>setStarted(false)}><ChevronLeft/> Sair</button><span>Questão {index+1} de {questions.length}</span><i><em style={{width:`${(index+1)/questions.length*100}%`}}/></i></div><div className="quiz-question"><small>{tracks.find(t=>t.id===q.track)?.code} · CONHECIMENTO APLICADO</small><h2>{q.question}</h2><div className="quiz-options">{q.options.map((o,i)=><button disabled={revealed} className={(answers[index]===i?'selected ':'')+(revealed&&i===q.answer?'correct ':'')+(revealed&&answers[index]===i&&i!==q.answer?'wrong':'')} onClick={()=>setAnswers(a=>({...a,[index]:i}))} key={o}><span>{String.fromCharCode(65+i)}</span>{o}{revealed&&i===q.answer&&<Check/>}</button>)}</div>{revealed&&<div className={answers[index]===q.answer?'answer-feedback correct':'answer-feedback'}><Lightbulb/><div><strong>{answers[index]===q.answer?'Resposta correta':'Ponto de revisão'}</strong><p>{q.explanation}</p></div></div>}<div className="quiz-actions">{!revealed?<button className="primary" disabled={answers[index]===undefined} onClick={()=>setRevealed(true)}>Confirmar resposta</button>:<button className="primary" onClick={next}>{index===questions.length-1?'Ver resultado':'Próxima questão'}<ArrowRight/></button>}</div></div></>}</section>}</div>}

function KnowledgeLibrary({state,openLesson}){const[tab,setTab]=useState('buscar'),[query,setQuery]=useState(''),[selectedTable,setSelectedTable]=useState(popData.tables.find(t=>!t.navigationOnly)?.id);const index=useMemo(()=>[...lessons.map(l=>({type:'seção',id:l.id,title:`${l.number||''} ${l.title}`.trim(),text:sectionText(l)})),...popData.tables.filter(t=>!t.navigationOnly).map(t=>({type:'tabela',id:t.id,title:t.caption,text:t.rows.map(r=>r.cells.map(c=>c.text).join(' ')).join(' ')}))],[]);const results=query.length>1?index.filter(x=>norm(x.title+' '+x.text).includes(norm(query))).slice(0,50):[];const table=tableMap.get(selectedTable);const glossary=popData.tables.find(t=>/siglas e abreviações/i.test(t.title));return <div className="page"><PageHeader title="Biblioteca operacional" subtitle="Pesquise no texto integral, abra os 61 quadros e tabelas e consulte todas as imagens do material-fonte." icon={Library}/><div className="library-tabs">{[['buscar','Buscar no POP',Search],['tabelas','Quadros e tabelas',Table2],['figuras','Figuras e fluxos',ImageIcon],['glossario','Glossário',BookMarked],['favoritos','Meus favoritos',Bookmark]].map(([id,l,I])=><button className={tab===id?'active':''} onClick={()=>setTab(id)} key={id}><I/>{l}</button>)}</div>{tab==='buscar'&&<section className="library-search"><div className="big-search"><Search/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Ex.: transferência de titularidade, PACUERA, APP, condicionante..."/><kbd>{results.length} resultados</kbd></div>{query.length<2?<div className="search-start"><Database/><h2>2.690 parágrafos pesquisáveis</h2><p>A busca percorre todas as seções e o conteúdo das tabelas, preservando o vínculo com a aula correspondente.</p><div>{['PACUERA','regra de transição','Licença de Operação','cartografia','condicionantes'].map(x=><button onClick={()=>setQuery(x)} key={x}>{x}</button>)}</div></div>:<div className="search-results">{results.map(r=><button key={r.id} onClick={()=>r.type==='seção'?openLesson(r.id):(setSelectedTable(r.id),setTab('tabelas'))}><span>{r.type}</span><div><strong>{r.title}</strong><p>{snippet(r.text,query)}</p></div><ChevronRight/></button>)}</div>}</section>}{tab==='tabelas'&&<div className="table-library"><aside><div><Filter/><span>61 tabelas · 2 índices ocultos na trilha</span></div>{popData.tables.filter(t=>!t.navigationOnly).map(t=><button className={selectedTable===t.id?'active':''} onClick={()=>setSelectedTable(t.id)} key={t.id}><span>{t.labelType} {t.labelNumber}</span><strong>{t.title}</strong></button>)}</aside><section>{table&&<TableRenderer table={table}/>}</section></div>}{tab==='figuras'&&<div className="figure-library"><h2>Figuras do POP</h2><div className="figure-grid">{popData.figures.map(f=><figure key={f.id}><button onClick={()=>window.open(f.publicPath,'_blank')}><img src={f.publicPath} alt={f.altText||f.title}/><span><Maximize2/></span></button><figcaption>{f.caption}</figcaption></figure>)}</div><h2>Fluxogramas comparados</h2><div className="flow-gallery">{flowData.flowcharts.map(f=><figure key={f.id}><a href={f.publicPath} target="_blank" rel="noreferrer"><img src={f.publicPath} alt={`${f.title} — ${f.variant}`}/></a><figcaption><span>{f.variant}</span><strong>{f.number}. {f.title}</strong></figcaption></figure>)}</div></div>}{tab==='glossario'&&<div className="glossary-view"><div><h2>Siglas e abreviações</h2><p>Consulta rápida extraída do Anexo E.</p></div>{glossary&&<TableRenderer table={glossary}/>}</div>}{tab==='favoritos'&&<div className="favorites-view">{state.bookmarks.length?state.bookmarks.map(id=>{let l=lessonMap.get(id);return l&&<button key={id} onClick={()=>openLesson(id)}><BookmarkCheck/><span><small>{tracks.find(t=>t.id===l.trackId)?.code}</small><strong>{l.number?`${l.number} `:''}{l.title}</strong></span><ChevronRight/></button>}):<Empty text="Você ainda não salvou nenhuma aula. Use o ícone de favorito no cabeçalho de uma aula."/>}</div>}</div>}

function GlobalSearch({close,openLesson}){const[q,setQ]=useState('');const input=useRef();useEffect(()=>input.current?.focus(),[]);const results=q.length>1?lessons.filter(l=>norm(l.title+' '+l.number+' '+sectionText(l)).includes(norm(q))).slice(0,12):[];return <div className="search-modal" role="dialog" aria-modal="true"><button className="modal-scrim" onClick={close} aria-label="Fechar busca"/><section><div className="modal-input"><Search/><input ref={input} value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar no POP e nas aulas..."/><kbd>ESC</kbd></div>{q.length<2?<div className="modal-empty"><Sparkles/><p>Pesquise uma fase, documento, norma, sigla ou critério.</p></div>:<div className="modal-results">{results.map(l=><button onClick={()=>openLesson(l.id)} key={l.id}><span>{tracks.find(t=>t.id===l.trackId)?.code}</span><div><strong>{l.number?`${l.number} `:''}{l.title}</strong><small>{snippet(sectionText(l),q)}</small></div><ChevronRight/></button>)}{!results.length&&<Empty text="Nenhum tópico encontrado. Tente outro termo."/>}</div>}<footer><span><kbd>↵</kbd> abrir</span><span><kbd>ESC</kbd> fechar</span><small>Busca local — nenhum dado é enviado</small></footer></section></div>}
function snippet(text,q){let clean=(text||'').replace(/\s+/g,' ').trim();let pos=norm(clean).indexOf(norm(q));if(pos<0)return clean.slice(0,180)+(clean.length>180?'…':'');return(pos>45?'…':'')+clean.slice(Math.max(0,pos-45),pos+145)+(pos+145<clean.length?'…':'')}
function PageHeader({title,subtitle,icon:Icon}){return <header className="page-header"><span><Icon/></span><div><h1>{title}</h1><p>{subtitle}</p></div></header>}
function Empty({text}){return <div className="empty-state"><BookOpen/><p>{text}</p></div>}

createRoot(document.getElementById('root')).render(<App/>);
